let e=require("electron");e.contextBridge.exposeInMainWorld(`ess`,{listSources:()=>e.ipcRenderer.invoke(`picker:list`),chooseSource:t=>e.ipcRenderer.send(`picker:choose`,t),createSession:()=>e.ipcRenderer.invoke(`session:create`),notifyLive:t=>e.ipcRenderer.send(`share:live`,t),notifyStopped:()=>e.ipcRenderer.send(`share:stopped`),onStopRequested:t=>{e.ipcRenderer.on(`share:stop`,t)}});